const results = await browserjs(tabId, () => {
  // Let's get the results heading, count, and job cards
  const resultHeading = document.querySelector('h2, [class*="result-count"]')?.textContent?.trim();
  const headings = Array.from(document.querySelectorAll('h1, h2, h3')).map(h => ({
    tag: h.tagName,
    text: h.textContent.trim()
  }));

  const jobCards = Array.from(document.querySelectorAll('[data-job-id], article, [class*="job-card"], [class*="search-results"] li')).map(el => {
    return {
      text: el.innerText?.trim()
    };
  }).filter(j => j.text && j.text.length > 20);

  return {
    url: window.location.href,
    headings,
    jobCardsText: jobCards.slice(0, 10)
  };
});

console.log("Search Results Overview:", JSON.stringify(results, null, 2));

