const tabId = 248688707;
const jobDetails = await browserjs(tabId, () => {
  // Let's find the job listing element
  const jobHeader = Array.from(document.querySelectorAll('h3')).find(h => h.textContent.includes('Human Resource Expert'));
  if (!jobHeader) return null;

  const container = jobHeader.closest('li') || jobHeader.closest('article') || jobHeader.parentElement;
  const links = Array.from(container.querySelectorAll('a')).map(a => ({ text: a.textContent.trim(), href: a.href }));

  return {
    headerText: jobHeader.textContent.trim(),
    containerText: container.innerText.trim(),
    links
  };
});

console.log("Job Details:", JSON.stringify(jobDetails, null, 2));

